-- Guards: exact scope and the current private Draft state; abort on drift.
do $$ begin
  if (select count(*) from libread_internal.issue139_publish_gut1_series_20261119) <> 48 then
    raise exception 'ISSUE139_GUT1_PUBLISH_SERIES_COUNT_MISMATCH';
  end if;
  if (select count(*) from libread_internal.issue139_publish_gut1_episodes_20261119) <> 2660 then
    raise exception 'ISSUE139_GUT1_PUBLISH_EPISODE_COUNT_MISMATCH';
  end if;
  -- Series: private, general rating, reviewed Gutenberg-batch rights metadata for the
  -- expected manifest, the owner-approved content warnings, one account.
  if exists (
    select 1
    from libread_internal.issue139_publish_gut1_series_20261119 t
    join public.series s on s.id = t.series_id
    where s.publication_status <> 'private'
       or s.is_public is distinct from false
       or s.content_rating <> 'general'
       or not (s.content_warnings @> t.expected_warnings and s.content_warnings <@ t.expected_warnings)
       or s.effect_settings->'publicDomain'->>'rightsChecked' is distinct from 'true'
       or s.effect_settings->'publicDomain'->>'manifestId' is distinct from t.manifest_id
       or s.effect_settings->'publicDomain'->>'sourceProvider' is distinct from 'Public domain'
       or s.effect_settings->'publicDomain'->>'sourceUrl' is not null
       or coalesce(s.effect_settings->'publicDomain'->>'edition', '') ilike '%gutenberg%'
  ) then raise exception 'ISSUE139_GUT1_PUBLISH_SERIES_STATE_DRIFT'; end if;
  if (select count(distinct s.author_id)
      from libread_internal.issue139_publish_gut1_series_20261119 t
      join public.series s on s.id = t.series_id) <> 1 then
    raise exception 'ISSUE139_GUT1_PUBLISH_AUTHOR_DRIFT';
  end if;
  -- Episodes: all Draft, never posted, numbered 1..n with the expected n.
  if exists (
    select 1 from libread_internal.issue139_publish_gut1_episodes_20261119
    where posting_status_before <> 'draft' or is_published_before
       or scheduled_for_before is not null or posted_at_before is not null
  ) then raise exception 'ISSUE139_GUT1_PUBLISH_EPISODE_STATE_DRIFT'; end if;
  if exists (
    select 1
    from libread_internal.issue139_publish_gut1_series_20261119 t
    left join libread_internal.issue139_publish_gut1_episodes_20261119 e on e.series_id = t.series_id
    group by t.series_id, t.expected_episodes
    having count(e.episode_id) <> t.expected_episodes
        or min(e.episode_number) <> 1
        or max(e.episode_number) <> t.expected_episodes
  ) then raise exception 'ISSUE139_GUT1_PUBLISH_EPISODE_NUMBERING_DRIFT'; end if;
end $$;

do $$
declare
  v_series integer;
  v_episodes integer;
begin
  update public.series s
    set publication_status = 'public', is_public = true
  from libread_internal.issue139_publish_gut1_series_20261119 t
  where s.id = t.series_id
    and s.publication_status = 'private' and s.is_public = false;
  get diagnostics v_series = row_count;
  if v_series <> 48 then
    raise exception 'ISSUE139_GUT1_PUBLISH_SERIES_ROWCOUNT_MISMATCH %', v_series;
  end if;

  update public.episodes e
    set posting_status = 'posted', is_published = true, posted_at = now()
  from libread_internal.issue139_publish_gut1_episodes_20261119 t
  where e.id = t.episode_id
    and e.posting_status = 'draft' and e.is_published = false and e.posted_at is null;
  get diagnostics v_episodes = row_count;
  if v_episodes <> 2660 then
    raise exception 'ISSUE139_GUT1_PUBLISH_EPISODE_ROWCOUNT_MISMATCH %', v_episodes;
  end if;

  update libread_internal.issue139_publish_gut1_episodes_20261119 t
    set posted_at_after = e.posted_at
  from public.episodes e
  where e.id = t.episode_id;

  -- The public read boundary (RLS policy + public_episode_work_summaries)
  -- must now expose exactly these 48 works with 2660 chapters.
  if (select count(*) from public.public_episode_work_summaries v
      join libread_internal.issue139_publish_gut1_series_20261119 t on t.series_id = v.series_id
      where v.episode_count = t.expected_episodes) <> 48 then
    raise exception 'ISSUE139_GUT1_PUBLISH_PUBLIC_VIEW_MISMATCH';
  end if;
end $$;
commit;

